INSERT INTO broadcast_text (Text,Text1,ID,LanguageID,ConditionID,EmotesID,Flags,ChatBubbleDurationMs,VoiceOverPriorityID,SoundKitID1,SoundKitID2,EmoteID1,EmoteID2,EmoteID3,EmoteDelay1,EmoteDelay2,EmoteDelay3,VerifiedBuild) VALUES ('The Amani were only the source of a bigger problem.','',298300,0,0,0,324,0,1,300080,0,0,0,0,0,0,0,70391);
INSERT INTO broadcast_text (Text,Text1,ID,LanguageID,ConditionID,EmotesID,Flags,ChatBubbleDurationMs,VoiceOverPriorityID,SoundKitID1,SoundKitID2,EmoteID1,EmoteID2,EmoteID3,EmoteDelay1,EmoteDelay2,EmoteDelay3,VerifiedBuild) VALUES ('The Lightbloom has never acted like this before. The forests had only small pockets of growth.','',298301,0,0,0,324,0,1,300081,0,0,0,0,0,0,0,70391);
INSERT INTO broadcast_text (Text,Text1,ID,LanguageID,ConditionID,EmotesID,Flags,ChatBubbleDurationMs,VoiceOverPriorityID,SoundKitID1,SoundKitID2,EmoteID1,EmoteID2,EmoteID3,EmoteDelay1,EmoteDelay2,EmoteDelay3,VerifiedBuild) VALUES ('But the moment the Sunwell surged--it changed everything. Every pocket of Lightbloom has grown into dense thickets, teeming with strange wildlife.','',298302,0,0,0,324,0,1,300082,0,0,0,0,0,0,0,70391);
INSERT INTO broadcast_text (Text,Text1,ID,LanguageID,ConditionID,EmotesID,Flags,ChatBubbleDurationMs,VoiceOverPriorityID,SoundKitID1,SoundKitID2,EmoteID1,EmoteID2,EmoteID3,EmoteDelay1,EmoteDelay2,EmoteDelay3,VerifiedBuild) VALUES ('I cannot leave this unchecked. Lor''themar said you had someone knowledgeable with you in Fairbreeze?','',298303,0,0,0,324,0,1,300083,0,0,0,0,0,0,0,70391);
INSERT INTO broadcast_text (Text,Text1,ID,LanguageID,ConditionID,EmotesID,Flags,ChatBubbleDurationMs,VoiceOverPriorityID,SoundKitID1,SoundKitID2,EmoteID1,EmoteID2,EmoteID3,EmoteDelay1,EmoteDelay2,EmoteDelay3,VerifiedBuild) VALUES ('I need to speak with them. My expertise lies with the forests. This problem, I can surely solve.','',298304,0,0,0,324,0,1,300084,0,0,0,0,0,0,0,70391);
INSERT INTO broadcast_text (Text,Text1,ID,LanguageID,ConditionID,EmotesID,Flags,ChatBubbleDurationMs,VoiceOverPriorityID,SoundKitID1,SoundKitID2,EmoteID1,EmoteID2,EmoteID3,EmoteDelay1,EmoteDelay2,EmoteDelay3,VerifiedBuild) VALUES ('The other issues... well, you''ve proven yourself competent many times over. Take care.','',298305,0,0,0,324,0,1,300085,0,0,0,0,0,0,0,70391);
